mapper.select:

SELECT min(running_lease_until)
FROM trusted_query.query_run
WHERE tenant_id = #{tenantId}
  AND status = 'RUNNING'
  AND running_lease_until > #{acceptedAt}


SELECT count(*) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
       ) AS accepted_queries,
       count(*) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
             AND status = 'ANSWERED'
       ) AS answered_queries,
       count(*) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
             AND status = 'REFUSED'
       ) AS refused_queries,
       count(*) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
             AND status = 'FAILED'
       ) AS failed_queries,
       count(*) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
             AND status = 'RUNNING'
       ) AS running_queries,
       coalesce(sum(input_tokens) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
       ), 0) AS input_tokens,
       coalesce(sum(output_tokens) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
       ), 0) AS output_tokens,
       coalesce(sum(total_tokens) FILTER (
           WHERE created_at >= #{from}
             AND created_at < #{to}
       ), 0) AS total_tokens,
       count(*) FILTER (
           WHERE created_at >= #{currentPeriodStart}
             AND created_at < #{currentPeriodEnd}
       ) AS daily_used,
       count(*) FILTER (
           WHERE status = 'RUNNING'
             AND running_lease_until > #{observedAt}
       ) AS concurrent_used
FROM trusted_query.query_run
WHERE tenant_id = #{tenantId}
